CREATE TABLE users (id VARCHAR(64) PRIMARY KEY, email VARCHAR(320) NOT NULL, email_normalized VARCHAR(320) NOT NULL UNIQUE, password_hash TEXT NOT NULL, first_name VARCHAR(120) NOT NULL DEFAULT '', last_name VARCHAR(120) NOT NULL DEFAULT '', display_name VARCHAR(240) NOT NULL DEFAULT '', status VARCHAR(32) NOT NULL DEFAULT 'pending', email_verified_at DATETIME NULL, last_login_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, deleted_at DATETIME NULL);
CREATE TABLE sessions (id VARCHAR(64) PRIMARY KEY, user_id VARCHAR(64) NOT NULL, token_hash VARCHAR(128) NOT NULL UNIQUE, user_agent TEXT NOT NULL, ip_address VARCHAR(64) NOT NULL DEFAULT '', expires_at DATETIME NOT NULL, last_seen_at DATETIME NULL, revoked_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE INDEX sessions_user_id_idx ON sessions(user_id);
CREATE TABLE email_verifications (id VARCHAR(64) PRIMARY KEY, user_id VARCHAR(64) NOT NULL, token_hash VARCHAR(128) NOT NULL UNIQUE, email VARCHAR(320) NOT NULL, expires_at DATETIME NOT NULL, consumed_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE password_resets (id VARCHAR(64) PRIMARY KEY, user_id VARCHAR(64) NOT NULL, token_hash VARCHAR(128) NOT NULL UNIQUE, expires_at DATETIME NOT NULL, consumed_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE login_attempts (id VARCHAR(64) PRIMARY KEY, email VARCHAR(320) NOT NULL DEFAULT '', user_id VARCHAR(64) NULL, ip_address VARCHAR(64) NOT NULL DEFAULT '', user_agent TEXT NOT NULL, successful BOOLEAN NOT NULL DEFAULT FALSE, failure_reason VARCHAR(255) NOT NULL DEFAULT '', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE auth_audit_events (id VARCHAR(64) PRIMARY KEY, user_id VARCHAR(64) NULL, event_type VARCHAR(64) NOT NULL, ip_address VARCHAR(64) NOT NULL DEFAULT '', user_agent TEXT NOT NULL, metadata JSON NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE roles (id VARCHAR(64) PRIMARY KEY, name VARCHAR(64) NOT NULL UNIQUE, description VARCHAR(255) NOT NULL DEFAULT '', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE permissions (id VARCHAR(64) PRIMARY KEY, resource VARCHAR(64) NOT NULL, action VARCHAR(64) NOT NULL, UNIQUE KEY permissions_resource_action (resource, action));
CREATE TABLE role_permissions (role_id VARCHAR(64) NOT NULL, permission_id VARCHAR(64) NOT NULL, PRIMARY KEY(role_id, permission_id), FOREIGN KEY(role_id) REFERENCES roles(id) ON DELETE CASCADE, FOREIGN KEY(permission_id) REFERENCES permissions(id) ON DELETE CASCADE);
CREATE TABLE user_roles (user_id VARCHAR(64) NOT NULL, role_id VARCHAR(64) NOT NULL, scope_type VARCHAR(64) NOT NULL DEFAULT '', scope_id VARCHAR(128) NOT NULL DEFAULT '', PRIMARY KEY(user_id, role_id, scope_type, scope_id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(role_id) REFERENCES roles(id) ON DELETE CASCADE);
CREATE TABLE organizations (id VARCHAR(64) PRIMARY KEY, name VARCHAR(255) NOT NULL, slug VARCHAR(255) NOT NULL UNIQUE, status VARCHAR(32) NOT NULL DEFAULT 'active', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE organization_members (organization_id VARCHAR(64) NOT NULL, user_id VARCHAR(64) NOT NULL, role_id VARCHAR(64) NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(organization_id, user_id), FOREIGN KEY(organization_id) REFERENCES organizations(id) ON DELETE CASCADE, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(role_id) REFERENCES roles(id) ON DELETE CASCADE);
